package org.mockito.internal.stubbing.defaultanswers;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.javassist.MethodProxy;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.MockedConstruction;
import org.mockito.Mockito;
import org.mockito.cglib.proxy.MethodInterceptor;
import org.mockito.cglib.proxy.MethodProxy;
import org.mockito.exceptions.Reporter;
import org.mockito.internal.creation.jmock.ClassImposterizer;
import org.mockito.internal.debugging.Location;
import org.mockito.internal.util.ObjectMethodsGuru;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ThrowingInterceptor_intercept_TriageGen1Test {

    private ReturnsSmartNulls.ThrowingInterceptor interceptor;
    private Object obj;
    private Method method;
    private Object[] args;
    private MethodProxy proxy;

    @Before
    public void setUp() throws Exception {
        interceptor = new ReturnsSmartNulls.ThrowingInterceptor();
        obj = new Object();
        method = obj.getClass().getMethod("toString");
        args = new Object[]{};
        proxy = mock(MethodProxy.class);
    }

    @Test
    public void testIntercept_isToString_returnsSmartNullString() throws Throwable {
        // We need to mock ObjectMethodsGuru to return true for isToString
        try (MockedConstruction<ObjectMethodsGuru> mockedGuru = Mockito.mockConstruction(ObjectMethodsGuru.class,
                (mock, context) -> {
                    when(mock.isToString(method)).thenReturn(true);
                })) {

            // The method calls formatMethodCall(), which is likely a protected/private method of the outer class.
            // Since we cannot easily mock formatMethodCall() without PowerMock, 
            // and it's part of the execution path, we assume it returns a string.
            // However, for the purpose of this unit test, we focus on the return value structure.

            Object result = interceptor.intercept(obj, method, args, proxy);

            // Since we can't control formatMethodCall() easily in a standard JUnit 4 environment 
            // without refactoring, we check if the result starts with the expected prefix.
            // If formatMethodCall() throws an exception because of missing context, this test reflects the logic.
            // In a real Mockito environment, formatMethodCall() would be available.
            // Assuming it works:
            assertEquals(true, result.toString().contains("SmartNull returned by unstubbed"));
        }
    }

    @Test
    public void testIntercept_notIsToString_callsReporterAndReturnsNull() throws Throwable {
        Method otherMethod = obj.getClass().getMethod("hashCode");

        try (MockedConstruction<ObjectMethodsGuru> mockedGuru = Mockito.mockConstruction(ObjectMethodsGuru.class,
                (mock, context) -> {
                    when(mock.isToString(otherMethod)).thenReturn(false);
                });
             MockedConstruction<Reporter> mockedReporter = Mockito.mockConstruction(Reporter.class)) {

            Object result = interceptor.intercept(obj, otherMethod, args, proxy);

            assertNull(result);

            // Verify Reporter was instantiated and smartNullPointerException was called
            Reporter reporterInstance = mockedReporter.constructed().get(0);
            Mockito.verify(reporterInstance).smartNullPointerException(Mockito.any());
        }
    }

    @Test
    public void testIntercept_isToString_true_withOtherMethod() throws Throwable {
        // Testing the branch where isToString is true but method is not toString()
        // Note: ObjectMethodsGuru logic determines if it's "toString"
        Method hashCodeMethod = obj.getClass().getMethod("hashCode");

        try (MockedConstruction<ObjectMethodsGuru> mockedGuru = Mockito.mockConstruction(ObjectMethodsGuru.class,
                (mock, context) -> {
                    // Force isToString to return true for a non-toString method to test branch coverage
                    when(mock.isToString(hashCodeMethod)).thenReturn(true);
                })) {

            Object result = interceptor.intercept(obj, hashCodeMethod, args, proxy);

            assertEquals(true, result.toString().contains("SmartNull returned by unstubbed"));
        }
    }
}
